import { expect, test } from "@playwright/test";

// Visual baseline of the public web screens of F15-F28 (web only), rendered against the LOCAL CONTRACT FIXTURE
// (scripts/fixture-api.mjs), never the real backend, so the pixels are deterministic.
// The baselines are machine output: they have NOT been reviewed by a person and the Linux ones are generated by CI
// (see docs/runbooks/visual-baselines.md). A passing run proves "unchanged since the baseline", not "approved".
const SLUG = "fixture-ana-y-luis";
const SCREENS: readonly { readonly name: string; readonly path: string; readonly lane: string }[] = [
  { name: "celebracion-publica", path: `/c/${SLUG}`, lane: "F08-F13" },
  { name: "rsvp-sin-enlace", path: `/c/${SLUG}/rsvp`, lane: "F15" },
  { name: "rsvp-enlace-invalido", path: `/c/${SLUG}/rsvp/${"x".repeat(43)}`, lane: "F15" },
  { name: "regalos-sin-credencial", path: `/c/${SLUG}/regalos`, lane: "F22" },
  { name: "directorio", path: "/proveedores", lane: "F24" },
  { name: "directorio-busqueda", path: "/proveedores/buscar?categoria=catering", lane: "F24" },
  { name: "directorio-categoria", path: "/proveedores/catering", lane: "F24" }
];
const WIDTHS = [360, 768, 1280] as const;

for (const screen of SCREENS) {
  for (const width of WIDTHS) {
    test(`${screen.lane} ${screen.name} ${width}px`, async ({ page }) => {
      await page.setViewportSize({ width, height: 900 });
      await page.emulateMedia({ colorScheme: "light", reducedMotion: "reduce" });
      await page.goto(screen.path, { waitUntil: "networkidle" });
      await page.evaluate(() => document.fonts.ready);
      // Lazy images only load once scrolled into view: walk the page, then wait for every image so the height is stable.
      await page.evaluate(async () => {
        const limit = Math.min(document.body.scrollHeight, 30 * window.innerHeight);
        for (let y = 0; y < limit; y += window.innerHeight) { window.scrollTo(0, y); await new Promise((resolve) => setTimeout(resolve, 60)); }
        window.scrollTo(0, 0);
        await Promise.all([...document.images].map((image) => (image.complete ? undefined : new Promise((resolve) => { image.onload = image.onerror = resolve; setTimeout(resolve, 5000); }))));
      });
      expect(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth)).toBe(true);
      await expect(page).toHaveScreenshot(`${screen.name}-${width}.png`, { fullPage: true });
    });
  }
}
